def enable_unaccent(apps, schema_editor):
    """Accent-insensitive search (US-10): 'dosemealti' finds 'Döşemealtı'.

    Never fails the deploy: if the database user may not create the extension, search
    falls back to accent-sensitive matching (crafts.search_support.has_unaccent).
    """
    if schema_editor.connection.vendor != "postgresql":
        return
    try:
        with transaction.atomic(using=schema_editor.connection.alias):
            schema_editor.execute("CREATE EXTENSION IF NOT EXISTS unaccent")
    except DatabaseError as error:
        print(f"\n  unaccent not enabled ({error}); search will match accents exactly.")


